use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_until_success() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 4,
        max_delay_ms: 6,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 => Err(RetryError::Transient("temporary outage".into())),
            2 => Err(RetryError::Transient("still unavailable".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![4, 6]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 1,
        max_delay_ms: 10,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

hunks.new:
#[test]
fn zero_max_attempts_still_makes_one_call() {
    let config = RetryConfig {
        max_attempts: 0,
        base_delay_ms: 10,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn zero_max_delay_disables_waiting_and_saturates_to_zero() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 10,
        max_delay_ms: 0,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![0, 0]);
}

